function annSvg(a,V,s,live){const z=V.z;const[p,q]=[a.pts[0],a.pts[1]||a.pts[0]];const col='#e8594a';const sw=2/z;if(a.t==='text')return `<text data-an="${a.id||''}" x="${p[0]}" y="${p[1]}" style="font:700 ${14/z}px system-ui;fill:${col}">${esc(a.s||'')}</text>`;
  if(a.t==='dim'){const L=Math.hypot(q[0]-p[0],q[1]-p[1]);const ang=Math.atan2(q[1]-p[1],q[0]-p[0]);const nx=-Math.sin(ang)*6/z,ny=Math.cos(ang)*6/z;return `<g data-an="${a.id||''}"><line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" stroke="${col}" stroke-width="${sw}"/><line x1="${p[0]-nx}" y1="${p[1]-ny}" x2="${p[0]+nx}" y2="${p[1]+ny}" stroke="${col}" stroke-width="${sw}"/><line x1="${q[0]-nx}" y1="${q[1]-ny}" x2="${q[0]+nx}" y2="${q[1]+ny}" stroke="${col}" stroke-width="${sw}"/><text x="${(p[0]+q[0])/2}" y="${(p[1]+q[1])/2-6/z}" class="tkl" style="font-size:${12/z}px;fill:${col}">${s?ftIn(L*s):'no scale'}</text></g>`}
  if(a.t==='arrow'){const ang=Math.atan2(q[1]-p[1],q[0]-p[0]),hh=12/z;return `<g data-an="${a.id||''}"><line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" stroke="${col}" stroke-width="${sw}"/><polygon points="${q[0]},${q[1]} ${q[0]-hh*Math.cos(ang-.4)},${q[1]-hh*Math.sin(ang-.4)} ${q[0]-hh*Math.cos(ang+.4)},${q[1]-hh*Math.sin(ang+.4)}" fill="${col}"/></g>`}
  if(a.t==='cloud')return `<path data-an="${a.id||''}" d="${cloudPath(p[0],p[1],q[0],q[1],8/z)}" fill="none" stroke="${col}" stroke-width="${sw}"/>`;
  return `<rect data-an="${a.id||''}" x="${Math.min(p[0],q[0])}" y="${Math.min(p[1],q[1])}" width="${Math.abs(q[0]-p[0])}" height="${Math.abs(q[1]-p[1])}" fill="none" stroke="${col}" stroke-width="${sw}"/>`}
function legendRows(pg){const p=cur();return p.conds.filter(c=>!TK.layOff.includes(c.layer||'Default')&&p.meas.some(m=>m.cid===c.id&&m.page===pg)).map(c=>{const R=condRes(p,c,pg);return {c,vals:R.vals}})}
function legendSvg(V){const rows=legendRows(V.page);if(!rows.length)return '';const z=V.z;const fs=11/z,lh=16/z;const w=Math.max(...rows.map(r=>(r.c.no+'  '+r.c.name+'  '+r.vals.map(v=>n2(v.v)+' '+v.u).join('  ')).length))*fs*.58+30/z;const hgt=(rows.length+1)*lh+10/z;const x=V.size[0]-w-14/z,y=14/z;
  return `<g class="tklegend" pointer-events="none"><rect x="${x}" y="${y}" width="${w}" height="${hgt}" fill="#fff" fill-opacity=".92" stroke="#333" stroke-width="${1/z}"/><text x="${x+8/z}" y="${y+lh}" style="font:800 ${fs}px system-ui;fill:#333">LEGEND — ${esc(cur().name)} · p.${V.page}</text>${rows.map((r,i)=>`<rect x="${x+8/z}" y="${y+lh*(i+1)+4/z}" width="${10/z}" height="${10/z}" fill="${r.c.color}"/><text x="${x+24/z}" y="${y+lh*(i+2)}" style="font:${fs}px system-ui;fill:#333">${esc(r.c.no)}  ${esc(r.c.name)}   ${r.vals.map(v=>n2(v.v)+' '+v.u).join('   ')}</text>`).join('')}</g>`}

/* ---------- Summary / Worksheet ---------- */
function summary(pane){const p=cur();const g=TK.sumBy;const n=TK.v&&TK.v.pdf?TK.v.pdf.numPages:(p.pages||[]).length||Math.max(1,...p.meas.map(m=>m.page));const dec=TK.dec;const f=v=>Number(v).toLocaleString('en-US',{minimumFractionDigits:dec,maximumFractionDigits:dec});
  const row=(c,pg,area)=>{const R=condRes(p,c,pg,area);const v=[0,1,2].map(i=>R.vals[i]);if(!v[0]||(!v[0].v&&TK.hideZero))return '';return `<tr><td>${esc(c.no)}</td><td><i class="tksw" style="background:${c.color};display:inline-block;margin-right:6px"></i>${esc(c.name)}</td><td>${esc(c.t2||'')}</td><td>${esc(c.slope||'')}</td><td>${condH(c)?ftIn(condH(c)):''}</td>${v.map(x=>`<td class="n">${x?f(x.v):''}</td><td>${x?x.u:''}</td>`).join('')}<td>${esc(c.notes||'')}</td></tr>`};
  let body='';const hdr=t=>`<tr class="ostg"><td colspan="12">${esc(t)}</td></tr>`;
  if(g==='page'){for(let pg=1;pg<=n;pg++){const L=p.conds.filter(c=>p.meas.some(m=>m.cid===c.id&&m.page===pg));if(!L.length)continue;body+=hdr(`Page ${pg} ${pageInfo(pg).sheet||''} ${pageInfo(pg).name||''}`)+L.map(c=>row(c,pg)).join('')}}
  else if(g==='area'){const A=['',...(p.areas||[])];A.forEach(a=>{const L=p.conds.filter(c=>p.meas.some(m=>m.cid===c.id&&(m.area||'')===a));if(!L.length)return;body+=hdr(a||'(unassigned)')+L.map(c=>row(c,0,a||'')).join('')})}
  else if(g==='type'){const G={};p.conds.forEach(c=>{const k=c.t2||({area:'Area',linear:'Linear',count:'Count'})[c.type];(G[k]=G[k]||[]).push(c)});Object.entries(G).forEach(([k,L])=>body+=hdr(k)+L.map(c=>row(c,0)).join(''))}
  else body=p.conds.map(c=>row(c,0)).join('');
  pane.innerHTML=`<div class="tkbar"><b>Summary</b><span class="ostpg">${[['type','Group by Type'],['area','By Bid Area'],['page','By Page'],['none','Flat']].map(([k,l])=>`<button type="button" data-sg="${k}" aria-pressed="${g===k}">${l}</button>`).join('')}</span><label class="muted" style="font-size:12px">Decimals <select id="sumDec">${[0,1,2,3].map(d=>`<option ${dec===d?'selected':''}>${d}</option>`).join('')}</select></label><label class="chk" style="font-size:12px"><input type="checkbox" id="sumHz" ${TK.hideZero?'checked':''}> Hide conditions with no quantity</label><span style="flex:1"></span><button class="btn small" id="sumX">Export to Excel</button></div>
   <div class="panel" style="overflow:auto"><table class="osttbl"><thead><tr><th>No.</th><th>Name</th><th>Type</th><th>Slope</th><th>Height</th><th>Quantity1</th><th>UOM1</th><th>Quantity2</th><th>UOM2</th><th>Quantity3</th><th>UOM3</th><th>Notes</th></tr></thead><tbody>${body||'<tr><td colspan="12" class="muted">No takeoff yet</td></tr>'}</tbody></table></div>`;
  pane.querySelectorAll('[data-sg]').forEach(b=>b.onclick=()=>{TK.sumBy=b.dataset.sg;summary(pane)});pane.querySelector('#sumDec').onchange=e=>{TK.dec=+e.target.value;summary(pane)};pane.querySelector('#sumHz').onchange=e=>{TK.hideZero=e.target.checked;summary(pane)};pane.querySelector('#sumX').onclick=exportXls}
function worksheet(pane){const p=cur();pane.innerHTML=`<div class="tkbar"><b>Worksheet</b><span class="muted" style="font-size:12px">Type a Manual Qty for items with no takeoff (or to add to it). It flows to Summary and Estimate.</span></div><div class="panel" style="overflow:auto"><table class="osttbl"><thead><tr><th>No.</th><th>Name</th><th>Style</th><th>Takeoff Qty1</th><th>Manual Qty</th><th>Total Qty1</th><th>UOM</th></tr></thead><tbody>${p.conds.map(c=>{const mq=num(c.mq);const R=condRes(p,c);const v=R.vals[0];return `<tr><td>${esc(c.no)}</td><td>${esc(c.name)}</td><td>${c.type==='area'?'Area':c.type==='linear'?'Linear':'Count'}</td><td class="n">${v?n2(v.v-mq):''}</td><td><input class="sm n" data-mq="${c.id}" value="${esc(c.mq||'')}" style="width:90px"></td><td class="n"><b>${v?n2(v.v):''}</b></td><td>${v?v.u:''}</td></tr>`}).join('')}</tbody></table></div>`;
  pane.querySelectorAll('[data-mq]').forEach(i=>i.onchange=()=>{const c=p.conds.find(x=>x.id===i.dataset.mq);c.mq=i.value.trim();save();worksheet(pane)})}
function exportXls(){const p=cur();if(!window.XLSX){toast('Excel library not loaded yet');return}const rows=[['No.','Name','Type','Style','Slope','Height (ft)','Quantity1','UOM1','Quantity2','UOM2','Quantity3','UOM3','Notes']];p.conds.forEach(c=>{const R=condRes(p,c);const v=[0,1,2].map(i=>R.vals[i]);rows.push([c.no,c.name,c.t2||'',c.type,c.slope||'',condH(c)||'',...v.flatMap(x=>x?[Math.round(x.v*100)/100,x.u]:['','']),c.notes||''])});
  const byA=[['Bid Area','No.','Name','Quantity1','UOM1','Quantity2','UOM2','Quantity3','UOM3']];['',...(p.areas||[])].forEach(a=>p.conds.forEach(c=>{const R=condRes(p,c,0,a||'');const v=[0,1,2].map(i=>R.vals[i]);if(v[0]&&v[0].v)byA.push([a||'(unassigned)',c.no,c.name,...v.flatMap(x=>x?[Math.round(x.v*100)/100,x.u]:['',''])])}));
  const byP=[['Page','Sheet','No.','Name','Quantity1','UOM1']];const n=Math.max(1,...p.meas.map(m=>m.page));for(let pg=1;pg<=n;pg++)p.conds.forEach(c=>{const R=condRes(p,c,pg);const v=R.vals[0];if(v&&v.v)byP.push([pg,(pageInfo(pg).sheet||'')+' '+(pageInfo(pg).name||''),c.no,c.name,Math.round(v.v*100)/100,v.u])});
  const det=[['Condition','Page','Bid Area','Quantity','Unit','Negative']];p.meas.forEach(m=>{const c=p.conds.find(x=>x.id===m.cid);if(c)det.push([c.name,m.page,m.area||'',Math.round((measQty(p,m)||0)*100)/100,UNIT[c.type],m.negq?'Y':''])});
  const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows),'Summary');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(byA),'By Area');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(byP),'By Page');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(det),'Objects');XLSX.writeFile(wb,`Takeoff_${p.name.replace(/[^\w]+/g,'_')}.xlsx`)}

/* ---------- Print / export marked-up plans ---------- */
function printDlg(){const p=cur();$('#dlgRoot').innerHTML=`<div class="scrim sheet"><div class="dlg"><h3>Print / Export plans with takeoff</h3><div class="qlabel">Range</div><label class="chk"><input type="radio" name="prR" value="tk" checked> Pages with takeoff</label> <label class="chk"><input type="radio" name="prR" value="cur"> Current page</label> <label class="chk"><input type="radio" name="prR" value="all"> All pages</label>
   <label class="chk" style="display:block;margin-top:10px"><input type="checkbox" id="prLeg" checked> Image Legend on each page</label><label class="chk" style="display:block"><input type="checkbox" id="prLab"> Quantity labels on objects</label><label class="chk" style="display:block"><input type="checkbox" id="prFoot" checked> Footer (project · page · date)</label>
   <div class="bar"><button class="btn" id="prX">Cancel</button><button class="go" id="prGo" style="width:auto">Build PDF</button></div></div></div>`;
  $('#prX').onclick=closeDlg;$('#prGo').onclick=async()=>{const r=document.querySelector('[name=prR]:checked').value,leg=$('#prLeg').checked,lab=$('#prLab').checked,foot=$('#prFoot').checked;closeDlg();toast('Building PDF…');try{const out=await buildPdf(r,leg,lab,foot);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([out],{type:'application/pdf'}));a.download=`Takeoff_${p.name.replace(/[^\w]+/g,'_')}.pdf`;document.body.appendChild(a);a.click();a.remove()}catch(e){toast('Could not build: '+(e.message||e))}}}
async function buildPdf(range,leg,lab,foot){const p=cur();await pdflib();const{PDFDocument,rgb,StandardFonts,degrees}=PDFLib;const src=await PDFDocument.load(await (BLOB[p.path]||await getPlan(p)).arrayBuffer());const n=src.getPageCount();const keep=[];for(let i=1;i<=n;i++){if(range==='all'||(range==='cur'&&i===TK.v.page)||(range==='tk'&&p.meas.some(m=>m.page===i)))keep.push(i)}
  const out=await PDFDocument.create();const font=await out.embedFont(StandardFonts.Helvetica),fb=await out.embedFont(StandardFonts.HelveticaBold);const col=h=>{const k=parseInt(String(h||'#000').slice(1),16);return rgb((k>>16&255)/255,(k>>8&255)/255,(k&255)/255)};
  const ps=await out.copyPages(src,keep.map(i=>i-1));ps.forEach((pg,k)=>{const i=keep[k];out.addPage(pg);const rot=(p.rot||{})[i];if(rot)pg.setRotation(degrees(rot));const H=pg.getHeight(),W=pg.getWidth();const Y=y=>H-y;const s=scaleOf(p,i);
    p.meas.filter(m=>m.page===i).forEach(m=>{const c=p.conds.find(x=>x.id===m.cid);if(!c||TK.layOff.includes(c.layer||'Default'))return;const cc=col(c.color);const lw=c.lw||2;
      if(c.type==='area'){pg.drawSvgPath('M'+m.pts.map(q=>q.join(',')).join(' L')+' Z',{x:0,y:H,borderColor:cc,borderWidth:lw,color:m.neg?rgb(1,1,1):cc,opacity:m.neg?.6:.2,borderDashArray:m.neg?[5,3]:undefined});if(lab&&s){const cx=m.pts.reduce((a,q)=>a+q[0],0)/m.pts.length,cy=m.pts.reduce((a,q)=>a+q[1],0)/m.pts.length;pg.drawText(n2(measQty(p,m)||0)+' SF',{x:cx,y:Y(cy),size:9,font:fb,color:cc})}}
      else if(c.type==='linear'){for(let k=1;k<m.pts.length;k++)pg.drawLine({start:{x:m.pts[k-1][0],y:Y(m.pts[k-1][1])},end:{x:m.pts[k][0],y:Y(m.pts[k][1])},thickness:lw*1.6,color:cc,opacity:.9});if(lab&&s){const a=m.pts[Math.floor(m.pts.length/2)];pg.drawText(n2(measQty(p,m)||0)+' LF',{x:a[0],y:Y(a[1]-6),size:9,font:fb,color:cc})}}
      else m.pts.forEach((q,k)=>{pg.drawCircle({x:q[0],y:Y(q[1]),size:5,color:cc});pg.drawText(String(k+1),{x:q[0]-2.5,y:Y(q[1]+3),size:7,font:fb,color:rgb(1,1,1)})})});
    ((p.ann||{})[i]||[]).forEach(a=>{const cc=rgb(.91,.35,.29);const[q1,q2]=[a.pts[0],a.pts[1]||a.pts[0]];if(a.t==='text')pg.drawText(String(a.s||''),{x:q1[0],y:Y(q1[1]),size:12,font:fb,color:cc});else if(a.t==='rect')pg.drawRectangle({x:Math.min(q1[0],q2[0]),y:Y(Math.max(q1[1],q2[1])),width:Math.abs(q2[0]-q1[0]),height:Math.abs(q2[1]-q1[1]),borderColor:cc,borderWidth:2});else if(a.t==='cloud')pg.drawSvgPath(cloudPath(q1[0],q1[1],q2[0],q2[1],8),{x:0,y:H,borderColor:cc,borderWidth:2});else{pg.drawLine({start:{x:q1[0],y:Y(q1[1])},end:{x:q2[0],y:Y(q2[1])},thickness:2,color:cc});if(a.t==='dim'&&s)pg.drawText(ftIn(Math.hypot(q2[0]-q1[0],q2[1]-q1[1])*s),{x:(q1[0]+q2[0])/2,y:Y((q1[1]+q2[1])/2-6),size:9,font:fb,color:cc})}});
    if(leg){const rows=legendRows(i);if(rows.length){const fs=9,lh=13;const w=Math.max(...rows.map(r=>(r.c.no+'  '+r.c.name+'  '+r.vals.map(v=>n2(v.v)+' '+v.u).join('  ')).length))*fs*.55+30;const hgt=(rows.length+1)*lh+10;const x=W-w-14,y=14;pg.drawRectangle({x,y:Y(y+hgt),width:w,height:hgt,color:rgb(1,1,1),opacity:.92,borderColor:rgb(.2,.2,.2),borderWidth:.8});pg.drawText(`LEGEND — ${p.name} · p.${i}`,{x:x+8,y:Y(y+lh),size:fs,font:fb,color:rgb(.2,.2,.2)});rows.forEach((r,k)=>{pg.drawRectangle({x:x+8,y:Y(y+lh*(k+1)+13),width:9,height:9,color:col(r.c.color)});pg.drawText(`${r.c.no}  ${r.c.name}   ${r.vals.map(v=>n2(v.v)+' '+v.u).join('   ')}`.replace(/[^\x20-\x7e]/g,''),{x:x+24,y:Y(y+lh*(k+2)),size:fs,font,color:rgb(.2,.2,.2)})})}}
    if(foot)pg.drawText(`${p.no||''} ${p.name} · ${(pageInfo(i).sheet||'')+' '+(pageInfo(i).name||'')} · page ${i} · ${scaleLabel(s)} · ${new Date().toLocaleDateString()} · ${me()} · CONFIDENTIAL — AME Builders`.replace(/[^\x20-\x7e]/g,''),{x:14,y:8,size:7,font,color:rgb(.3,.3,.3)})});
  return await out.save()}

document.head.insertAdjacentHTML('beforeend',`<style>.ostset{display:inline-flex;gap:8px;align-items:center;font-size:12px;color:var(--muted)}.ostset select{font:inherit;font-size:12px;padding:4px 6px;max-width:180px}.ostcg.muted{opacity:.45}.ostcg .tkce{border:0;background:none;color:var(--muted);cursor:pointer}.tklegend text{paint-order:stroke}#tkCtx button{font-size:13px}</style>`);
