if(!window.__plFs){window.__plFs=1;const fsSet=(sec,on)=>{sec.classList.toggle('appfs',on);document.body.style.overflow=on?'hidden':'';sec.querySelectorAll('.plFsB').forEach(b=>{b.setAttribute('aria-pressed',on);b.title=on?'Exit full screen (Esc)':'Full screen'});setTimeout(()=>{if(TK.v&&TK.v.pdf&&sec.id==='tab-tko')TK.v.fit();if(sec.id==='tab-mkp'&&window.__revuFit)window.__revuFit()},60)};
  document.addEventListener('click',e=>{const b=e.target.closest('.plFsB');if(!b)return;const sec=b.closest('section');if(sec)fsSet(sec,!sec.classList.contains('appfs'))});
  window.addEventListener('keydown',e=>{if(e.key!=='Escape')return;const sec=document.querySelector('section.appfs');if(sec&&!document.querySelector('#dlgRoot .scrim'))fsSet(sec,false)})}
